    private static List<string[]> Parse(string csv)
    {
        List<string[]> rows=new List<string[]>();List<string> cells=new List<string>();StringBuilder cell=new StringBuilder();bool quoted=false;
        for(int i=0;i<csv.Length;i++){char c=csv[i];if(c=='"'){if(quoted&&i+1<csv.Length&&csv[i+1]=='"'){cell.Append('"');i++;}else quoted=!quoted;}
            else if(c==','&&!quoted){cells.Add(cell.ToString());cell.Length=0;}else if(c=='\r'&&!quoted){Check(i+1<csv.Length&&csv[i+1]=='\n',"CSV row CRLF");i++;cells.Add(cell.ToString());rows.Add(cells.ToArray());cells.Clear();cell.Length=0;}else cell.Append(c);}
        Check(!quoted&&cells.Count==0&&cell.Length==0,"CSV complete quoted rows");foreach(string[] row in rows)Check(row.Length==9,"CSV stable nine-column schema");return rows;
    }
